&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Soho House, the&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;strong&gt;Senior &lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Events Manager&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;is &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;responsible for supporting the booking, supervision and realisation of private events for members at Soho House.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;The Senior Events Manager is also an ambassador for the Soho House brand and fully embraces our ethos, supports staff, member and guest experience.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
